using System.Linq;
using System.Windows.Forms;

public sealed partial class CompanionWindow {
    DriverHistoryService driverHistoryService;
    DriverAnalysisOptions driverAnalysisOptions;
    DateTime nextDriverHistoryFetch=DateTime.MinValue;
    sealed class AnalysisDriver {
        public string Key,Name,Class;
        public override string ToString(){return Name+(string.IsNullOrEmpty(Class)?"":" · "+Class);}
    }
    sealed class AnalysisLap {public DriverLapPoint Lap;public override string ToString(){return "V"+Lap.Number+" · "+TimingData.Lap(Lap.Time);}}
    ComboBox AnalysisChoice(string name,int width){var control=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,DrawMode=DrawMode.OwnerDrawFixed,ItemHeight=P(24),FlatStyle=FlatStyle.Flat,BackColor=GtcTheme.Input,ForeColor=GtcTheme.Text,Font=F(11),Width=P(width),AccessibleName=name};control.DrawItem+=(s,e)=>{using(var brush=new SolidBrush((e.State&DrawItemState.Selected)!=0?GtcTheme.AccentSurface:GtcTheme.Input))e.Graphics.FillRectangle(brush,e.Bounds);if(e.Index>=0)TextRenderer.DrawText(e.Graphics,AppLanguage.T(Convert.ToString(control.Items[e.Index])),control.Font,e.Bounds,GtcTheme.Text,TextFormatFlags.VerticalCenter|TextFormatFlags.Left|TextFormatFlags.EndEllipsis);e.DrawFocusRectangle();};return control;}
    void StartDriverHistory(){
        driverHistoryService=new DriverHistoryService();driverAnalysisOptions=CompanionStore.Read<DriverAnalysisOptions>(Path.Combine("training","analysis-options.json"))??new DriverAnalysisOptions();
    }
    async void ObserveDriverHistory(){
        driverHistoryService.Collector.Local(trainingReader.Activity,DateTime.UtcNow);
        try{driverHistoryService.Save();}catch{ /* Collection continues if the disk is temporarily unavailable. */ }
        if(driverAnalysisOptions.BackgroundGtc&&DateTime.UtcNow>=nextDriverHistoryFetch){nextDriverHistoryFetch=DateTime.UtcNow.AddSeconds(15);var profile=CompetitionProfiles.Selected(settings);if(profile!=null)await driverHistoryService.Fetch(profile.TimingId);}
    }
    void ShowDriverAnalysis(){StopCountdown();using(var dialog=CreateDriverAnalysis(false))dialog.ShowDialog(this);}
    Form CreateDriverAnalysis(bool preview){
        var dialog=new Form{Text="Pilotos e stints",Icon=BrandIcon(),BackColor=GtcTheme.Background,ForeColor=GtcTheme.Text,Font=F(11),AutoScaleMode=AutoScaleMode.None,StartPosition=FormStartPosition.CenterParent,ClientSize=new Size(P(900),P(760)),MinimumSize=new Size(P(760),P(650))};
        var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(P(18)),ColumnCount=1,RowCount=8};root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));for(int i=0;i<8;i++)root.RowStyles.Add(new RowStyle(i==5?SizeType.Percent:SizeType.AutoSize,i==5?100:0));dialog.Controls.Add(root);
        var heading=TextLabel("Pilotos e stints",19,true);heading.Margin=new Padding(0,0,0,P(5));root.Controls.Add(heading,0,0);
        var intro=TextLabel("GTC prioritária · voltas em falta preenchidas localmente quando a sessão coincide",11);intro.ForeColor=GtcTheme.Muted;intro.Margin=new Padding(0,0,0,P(16));root.Controls.Add(intro,0,1);
        var selectors=new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,ColumnCount=3,Margin=new Padding(0,0,0,P(12))};selectors.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,27));selectors.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,47));selectors.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,26));root.Controls.Add(selectors,0,2);
        Func<string,int,ComboBox> combo=(name,col)=>{var label=TextLabel(name,10);label.ForeColor=GtcTheme.Muted;label.Margin=new Padding(0,0,0,P(5));selectors.Controls.Add(label,col,0);var control=new ComboBox{Dock=DockStyle.Top,DropDownStyle=ComboBoxStyle.DropDownList,DrawMode=DrawMode.OwnerDrawFixed,ItemHeight=P(24),FlatStyle=FlatStyle.Flat,BackColor=GtcTheme.Input,ForeColor=GtcTheme.Text,Font=F(11),Margin=new Padding(0,0,col==2?0:P(10),0),AccessibleName=name,DropDownWidth=P(col==1?560:320)};control.DrawItem+=(s,e)=>{using(var brush=new SolidBrush((e.State&DrawItemState.Selected)!=0?GtcTheme.AccentSurface:GtcTheme.Input))e.Graphics.FillRectangle(brush,e.Bounds);if(e.Index>=0)TextRenderer.DrawText(e.Graphics,AppLanguage.T(Convert.ToString(control.Items[e.Index])),control.Font,e.Bounds,GtcTheme.Text,TextFormatFlags.VerticalCenter|TextFormatFlags.Left|TextFormatFlags.EndEllipsis);e.DrawFocusRectangle();};selectors.Controls.Add(control,col,1);return control;};
        var drivers=combo("Piloto",0);var sessions=combo("Sessão / origem da recolha",1);var stints=combo("Stint",2);
        var actions=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,WrapContents=true,Margin=new Padding(0,0,0,P(10))};root.Controls.Add(actions,0,3);var fetch=Button("Atualizar GTC",140);fetch.Margin=new Padding(0,0,P(16),0);actions.Controls.Add(fetch);
        var background=new BrandCheck{Text="Recolher GTC em segundo plano",Checked=driverAnalysisOptions.BackgroundGtc,AutoSize=true,Font=F(11),ForeColor=GtcTheme.Text,Margin=new Padding(0,P(7),0,0)};actions.Controls.Add(background);
        var metric=AnalysisChoice("Analisar volta completa ou setor",140);metric.Items.AddRange(DriverLapAnalysis.Names);metric.SelectedIndex=(int)trainingChart.Metric;metric.Margin=new Padding(P(18),0,0,0);actions.Controls.Add(metric);
        var status=TextLabel("",11);status.ForeColor=GtcTheme.Muted;status.MaximumSize=new Size(P(840),0);status.Margin=new Padding(0,0,0,P(10));root.Controls.Add(status,0,4);
        var chart=new DriverAnalysisChart{Dock=DockStyle.Fill,Margin=Padding.Empty,Target=trainingOptions.Target,Tolerance=trainingOptions.Tolerance};root.Controls.Add(chart,0,5);
        var detail=new TableLayoutPanel{AutoSize=true,Dock=DockStyle.Top,ColumnCount=4,Margin=new Padding(0,P(10),0,0),Padding=new Padding(P(10)),BackColor=GtcTheme.Surface};for(int col=0;col<4;col++)detail.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,25));root.Controls.Add(detail,0,6);var lapPicker=AnalysisChoice("Volta a analisar",195);lapPicker.Dock=DockStyle.Top;detail.Controls.Add(lapPicker,0,0);var detailReference=TextLabel("",10);detailReference.MaximumSize=new Size(P(590),0);detailReference.ForeColor=GtcTheme.Muted;detailReference.Margin=new Padding(P(10),P(4),0,P(8));detail.Controls.Add(detailReference,1,0);detail.SetColumnSpan(detailReference,3);var values=new Label[4];for(int col=0;col<4;col++){values[col]=TextLabel("—",11,true);values[col].Margin=new Padding(0,P(8),P(8),0);detail.Controls.Add(values[col],col,1);}
        var footer=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,WrapContents=true,Margin=new Padding(0,P(12),0,0)};root.Controls.Add(footer,0,7);var target=new BrandCheck{Text="Mostrar referência",Checked=true,AutoSize=true,Font=F(11),ForeColor=GtcTheme.Text,Margin=new Padding(0,P(7),P(18),0)};var other=new BrandCheck{Text="Incluir outras voltas",Checked=true,AutoSize=true,Font=F(11),ForeColor=GtcTheme.Text,Margin=new Padding(0,P(7),P(18),0)};var export=Button("Guardar gráfico",150);footer.Controls.Add(target);footer.Controls.Add(other);footer.Controls.Add(export);
        DateTime nextCsvRead=DateTime.MinValue;var csvRuns=new System.Collections.Generic.List<TrainingRun>();bool updating=false,sourceChosen=false,selectingLap=false;string driverKey="",sessionKey="",stintKey="",lapKey="";
        Func<DriverHistoryRecord,bool> visible=r=>r.Source!="gtc"||r.TimingId==0||CompetitionProfiles.Selected(settings)!=null&&r.TimingId==CompetitionProfiles.Selected(settings).TimingId;
        Action redraw=()=>{var record=sessions.SelectedItem as DriverHistoryRecord;var stint=stints.SelectedItem as DriverStintSlice;var available=record==null?new System.Collections.Generic.List<DriverLapPoint>():record.Points(stint);chart.Record=record;chart.Stint=stint;chart.Metric=(LapMetric)metric.SelectedIndex;chart.ShowTarget=target.Checked;chart.ShowOther=other.Checked;
            string key=(record==null?"":record.Id)+"|"+string.Join(",",available.Select(l=>l.Number));if(key!=lapKey){int number=lapPicker.SelectedItem is AnalysisLap?((AnalysisLap)lapPicker.SelectedItem).Lap.Number:0;lapKey=key;selectingLap=true;lapPicker.Items.Clear();foreach(var point in available)lapPicker.Items.Add(new AnalysisLap{Lap=point});lapPicker.SelectedItem=lapPicker.Items.Cast<AnalysisLap>().FirstOrDefault(l=>l.Lap.Number==number)??lapPicker.Items.Cast<AnalysisLap>().LastOrDefault();selectingLap=false;}
            var selected=lapPicker.SelectedItem as AnalysisLap;chart.SelectedLap=selected==null?0:selected.Lap.Number;chart.Invalidate();var reference=DriverLapAnalysis.Reference(available);detailReference.Text=(reference==null?"Sem volta limpa de referência":"Setores comparados com a melhor volta limpa da seleção · V"+reference.Number)+(selected==null?"":selected.Lap.Pit==true?" · Boxes":selected.Lap.Valid==false?" · Inválida (local)":selected.Lap.PossiblyInvalid?" · Possivelmente inválida (sem tempo GTC)":!selected.Lap.Complete?" · Dados incompletos":"");for(int col=0;col<4;col++){var value=selected==null?null:DriverLapAnalysis.Value(selected.Lap,(LapMetric)col);var baseline=DriverLapAnalysis.Value(reference,(LapMetric)col);values[col].Text=(col==0?"Volta":"S"+col)+"  "+DriverLapAnalysis.Format(value,(LapMetric)col)+(col>0&&value.HasValue&&baseline.HasValue?"\n"+TrainingMath.Delta(value.Value-baseline.Value):"");values[col].ForeColor=col>0&&value.HasValue&&baseline.HasValue?AnalysisLegend.Point(selected.Lap.Clean,value.Value,baseline):GtcTheme.Text;}
            if(record==null)status.Text="Ainda sem voltas GTC. Atualiza a GTC ou mantém o Companion aberto durante a sessão.";else status.Text=(record.Partial?"Histórico parcial":"Histórico disponível")+" · "+record.Laps.Count+"/"+record.TotalLaps+" voltas · "+available.Count(l=>l.DataSource=="local")+" locais sem tempo GTC; podem ser inválidas.";if(driverHistoryService.Error!=null&&!preview)status.Text+="\n"+driverHistoryService.Error;};
        Action refresh=null;
        refresh=()=>{
            if(updating)return;updating=true;
            var records=GtcHistoryMerge.Sessions(driverHistoryService.Collector.Book.Records.Where(r=>r.Source=="local"||visible(r))).Where(r=>r.Laps.Count>0).ToList();if(!preview&&DateTime.UtcNow>=nextCsvRead){nextCsvRead=DateTime.UtcNow.AddSeconds(5);csvRuns=TrainingStore.History();}var runs=csvRuns.Where(r=>training.Run==null||r.Id!=training.Run.Id).ToList();if(training.Run!=null)runs.Add(training.Run);GtcHistoryMerge.AttachCsvTires(records,runs);var list=records.GroupBy(r=>TimingData.Normalize(r.Driver)+"|"+TimingData.Normalize(r.Class)).Select(g=>new AnalysisDriver{Key=g.Key,Name=g.First().Driver,Class=g.First().Class}).OrderBy(d=>d.Name).ToList();
            string dk=string.Join(";",list.Select(d=>d.Key));if(dk!=driverKey){string selected=(drivers.SelectedItem as AnalysisDriver)==null?null:((AnalysisDriver)drivers.SelectedItem).Key;driverKey=dk;drivers.Items.Clear();drivers.Items.AddRange(list.Cast<object>().ToArray());var chosen=list.FirstOrDefault(d=>d.Key==selected)??list.FirstOrDefault(d=>TimingData.Normalize(d.Name)==TimingData.Normalize(settings.Driver))??list.FirstOrDefault();drivers.SelectedItem=chosen;}
            var pilot=drivers.SelectedItem as AnalysisDriver;var history=GtcDataPriority.Sessions(records.Where(r=>pilot!=null&&TimingData.Normalize(r.Driver)+"|"+TimingData.Normalize(r.Class)==pilot.Key));string sk=string.Join(";",history.Select(r=>r.Id+":"+r.Laps.Count+":"+r.DataRevision+":"+r.Laps.Count(l=>l.TireSource=="csv")));if(sk!=sessionKey){string selected=!sourceChosen||!(sessions.SelectedItem is DriverHistoryRecord)?null:((DriverHistoryRecord)sessions.SelectedItem).Id;sessionKey=sk;sessions.Items.Clear();sessions.Items.AddRange(history.Cast<object>().ToArray());sessions.SelectedItem=history.FirstOrDefault(r=>r.Id==selected)??history.FirstOrDefault();stintKey="";}
            var record=sessions.SelectedItem as DriverHistoryRecord;var slices=record==null?new System.Collections.Generic.List<DriverStintSlice>():record.Stints();string tk=(record==null?"":record.Id)+"|"+string.Join(";",slices.Select(s=>s.Number+":"+s.AfterLap+":"+s.ThroughLap+":"+s.FirstAvailable+":"+s.LastAvailable));if(tk!=stintKey){int selected=(stints.SelectedItem as DriverStintSlice)==null?0:((DriverStintSlice)stints.SelectedItem).Number;stintKey=tk;stints.Items.Clear();stints.Items.AddRange(slices.Cast<object>().ToArray());stints.SelectedItem=slices.FirstOrDefault(s=>s.Number==selected)??slices.FirstOrDefault();}
            updating=false;redraw();
        };
        drivers.SelectedIndexChanged+=(s,e)=>{if(!updating){sourceChosen=false;sessionKey="";refresh();}};sessions.SelectedIndexChanged+=(s,e)=>{if(!updating){sourceChosen=true;stintKey="";refresh();}};stints.SelectedIndexChanged+=(s,e)=>{if(!updating)redraw();};target.CheckedChanged+=(s,e)=>redraw();other.CheckedChanged+=(s,e)=>redraw();
        metric.SelectedIndexChanged+=(s,e)=>{trainingMetric.SelectedIndex=metric.SelectedIndex;redraw();};lapPicker.SelectedIndexChanged+=(s,e)=>{if(!selectingLap)redraw();};chart.LapSelected+=number=>{lapPicker.SelectedItem=lapPicker.Items.Cast<AnalysisLap>().FirstOrDefault(l=>l.Lap.Number==number);};
        background.CheckedChanged+=(s,e)=>{if(preview)return;driverAnalysisOptions.BackgroundGtc=background.Checked;Directory.CreateDirectory(Path.Combine(CompanionStore.Root,"training"));CompanionStore.Write(Path.Combine("training","analysis-options.json"),driverAnalysisOptions);nextDriverHistoryFetch=DateTime.MinValue;};
        Func<System.Threading.Tasks.Task> update=async()=>{if(preview)return;var profile=CompetitionProfiles.Selected(settings);if(profile==null||profile.TimingId<=0){status.Text="Escolhe um campeonato com classificação GTC para obter os dados online.";return;}fetch.Enabled=false;fetch.Text="A consultar…";await driverHistoryService.Fetch(profile.TimingId);if(dialog.IsDisposed)return;fetch.Enabled=true;fetch.Text="Atualizar GTC";refresh();};fetch.Click+=async(s,e)=>await update();
        export.Click+=(s,e)=>{if(chart.Record==null)return;using(var file=new SaveFileDialog{Filter="Imagem PNG|*.png",FileName="piloto-stints.png"})if(file.ShowDialog(dialog)==DialogResult.OK)try{chart.SaveImage(file.FileName);}catch(Exception){status.Text="Não foi possível guardar a imagem.";}};
        var timer=new System.Windows.Forms.Timer{Interval=1000};timer.Tick+=(s,e)=>refresh();dialog.Shown+=async(s,e)=>{refresh();if(!preview){timer.Start();await update();}};dialog.FormClosed+=(s,e)=>timer.Dispose();GtcWindowTheme.Attach(dialog);refresh();return dialog;
    }
    public void RenderDriverAnalysis(string destination,bool sectors=false){
        trainingOptions.Target=82.7;trainingOptions.Tolerance=.5;
        if(sectors)trainingMetric.SelectedIndex=1;
        var record=new DriverHistoryRecord{Id="demo",Driver="Piloto de demonstração",Class="Cup",Track="Circuito de demonstração",Source="gtc",FirstSeenUtc=DateTime.UtcNow,TotalLaps=24};double[] times={82.9,82.5,82.6,82.8,82.4,82.6,82.9,82.5,82.7,83.0,149,106,83.3,82.8,82.9,82.5,82.7,82.6,82.8,82.45,82.7,82.9,82.6,82.8};for(int i=0;i<times.Length;i++)if(i!=6&&i!=7)record.Put(new DriverLapPoint{Number=i+1,Time=times[i],Valid=i!=17,Pit=i==10||i==11,Complete=true,TireSource="csv",TireFL=.98-i*.004,TireFR=.97-i*.004,TireRL=.99-i*.003,TireRR=.98-i*.003,S1=i==2?(double?)null:18+(i%4)*.08,S2=33+(i%3)*.1,S3=times[i]-18-(i%4)*.08-33-(i%3)*.1});record.Visits.Add(new DriverPitVisit{EntryAfterLap=10,ExitAfterLap=11,ObservedUtc=DateTime.UtcNow,ExitObservedUtc=DateTime.UtcNow});driverHistoryService.Collector.Book.Records.Clear();driverHistoryService.Collector.Book.Records.Add(record);
        using(var dialog=CreateDriverAnalysis(true)){dialog.ShowInTaskbar=false;dialog.StartPosition=FormStartPosition.Manual;dialog.Location=new Point(-20000,-20000);dialog.Show();Application.DoEvents();using(var bitmap=new Bitmap(dialog.ClientSize.Width,dialog.ClientSize.Height)){dialog.Controls[0].DrawToBitmap(bitmap,new Rectangle(Point.Empty,dialog.ClientSize));bitmap.Save(destination);}dialog.Close();}
    }
